import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"第三章 数据管理","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/03-第三章-数据管理.md","filePath":"tutorial/03-第三章-数据管理.md","lastUpdated":1785684581000}'),c={name:"tutorial/03-第三章-数据管理.md"};function t(d,e,p,i,l,r){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="第三章-数据管理" tabindex="-1">第三章 数据管理 <a class="header-anchor" href="#第三章-数据管理" aria-label="Permalink to &quot;第三章 数据管理&quot;">​</a></h1><p>无论后续要做描述统计、假设检验还是回归建模，所有分析都建立在同一块基石之上：把原始信息整理成 PSPP 能够读懂的结构化数据。PSPP 处理的核心对象称为<strong>数据集</strong>（dataset），它由一张二维表格承载——纵向的每一列是一个<strong>变量</strong>（variable），横向的每一行是一个<strong>个案</strong>（case，也称观测，observation）。数据分析本质上就是围绕这张表，定义变量含义、录入或修改数值、筛选与变换个案，最终产出可供统计过程读取的干净数据。本章把数据管理的全链路讲透：从变量到底是什么、怎样新建并定义变量，到怎样录入、从外部文件导入、怎样深入设置属性，再到排序、拆分、筛选、计算新变量与重新编码，最后落到数据清洗与缺失值处理的收尾环节。</p><p>为便于前后呼应，本章贯穿一个小而完整的示例数据集：一份班级学生调查与成绩记录。它包含学号 <code>id</code>、姓名 <code>name</code>、班级 <code>class</code>、性别 <code>gender</code>、语文 <code>chinese</code>、数学 <code>math</code>、英语 <code>english</code>、满意度 <code>satisfaction</code>（1~5 分）与出勤率 <code>attendance</code>（0~100）。这份数据将反复出现在各节的示例中。</p><h2 id="_3-1-数据集与变量基础概念" tabindex="-1">3.1 数据集与变量基础概念 <a class="header-anchor" href="#_3-1-数据集与变量基础概念" aria-label="Permalink to &quot;3.1 数据集与变量基础概念&quot;">​</a></h2><p>理解 PSPP 的数据模型，关键在于厘清三件事物及其关系。一张数据集像一本名册：每一行记载一个具体对象（这里就是一名学生）的全部信息，称为一个个案；每一列描述所有对象共享的某一属性（如语文成绩），称为一个变量。同一个变量在不同个案上的取值各不相同，这些取值的全体构成该变量的一列数据。个案与变量交叉处的单个数字或文字，称作一个取值（value）。</p><p>PSPP 中的变量只有<strong>两种类型</strong>，这一点与许多现代表格软件不同，却正是统计软件严格性的来源：</p><ul><li><strong>numeric（数值型）</strong>：存放可以参与四则运算的数字，例如成绩、年龄、满意度评分。数值型变量支持计算、求均值、做方差分析等一切数学操作。</li><li><strong>string（字符串型）</strong>：存放文本，例如姓名、班级代号、开放性回答。字符串由字节序列构成，不能直接参与算术运算。定义时需用 <code>A</code> 加宽度标明最大字节数，例如 <code>name (A12)</code> 表示最多容纳 12 字节的字符串变量。</li></ul><p>二者的区分看似简单，却常常是初学者出错的根源：把应当是数值的列误建成字符串，后续 <code>COMPUTE</code>、<code>MEANS</code> 等过程便无法对该列求和；反之把本该是文本的列建成数值，中文姓名等非数字内容会被整列丢弃。因此，在录入之前先想清楚&quot;这一列将来要不要算数&quot;，远比事后补救来得经济。</p><p>在此还需铺垫一个与变量类型不同维度的概念——<strong>测量尺度</strong>（measurement level，PSPP 中称度量标准），它描述变量取值背后的数学含义，而非存储方式：</p><ul><li><strong>nominal（名义尺度）</strong>：取值仅代表类别，彼此无大小顺序，例如性别、班级、专业名称。</li><li><strong>ordinal（有序尺度）</strong>：取值有先后次序，但相邻间距未必相等，例如满意度 1~5 分、成绩等级。</li><li><strong>scale（标度尺度，也称连续/定距尺度）</strong>：取值既有顺序又有可比较的等距，通常可近似为连续量，例如语文、数学、英语分数与出勤率。</li></ul><p>测量尺度不影响数据存储，却直接关系到哪些统计过程适用、结果应如何解读。例如对名义变量求&quot;均值&quot;通常没有意义，而对标度变量做&quot;中位数&quot;虽可行却未必最优。PSPP 在过程层面会依据度量标准给出合适默认，因此从一开始就把尺度设对，能让后续分析少走弯路。下面的片段即用语法直观地展示了两类变量的声明方式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /id (F4) name (A12) gender (F1) chinese (F3).</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>1001 张伟  1  88</span></span>
<span class="line"><span>1002 李娜  2  92</span></span>
<span class="line"><span>END DATA.</span></span></code></pre></div><p>其中 <code>id</code>、<code>gender</code>、<code>chinese</code> 为数值型（<code>F</code> 起头指明数值格式），<code>name</code> 为字符串型（<code>A12</code>），二者混排于同一数据定义之中。运行后，数据集便拥有三列数值与一列文本，奠定了后续一切操作的结构基础。</p><h2 id="_3-2-新建数据文件与变量定义" tabindex="-1">3.2 新建数据文件与变量定义 <a class="header-anchor" href="#_3-2-新建数据文件与变量定义" aria-label="Permalink to &quot;3.2 新建数据文件与变量定义&quot;">​</a></h2><p>在图形界面 <code>psppire</code> 中新建数据，核心是 <strong>Variable View</strong>（变量视图）这一标签页（界面推断，手册未逐项文档化）。它把每个变量的属性横向铺成一排列，逐列设定即可完成变量定义。PSPP 的 Variable View 通常包含以下十列，理解每一列的职责，是规范建表的第一步：</p><ul><li><strong>名称（Name）</strong>：变量的唯一标识，须以字母开头、不含空格与中文，建议用英文或拼音缩写（如 <code>chinese</code>、<code>attendance</code>）。</li><li><strong>类型（Type）</strong>：在弹出的对话框中选择 numeric 或 string，并据此设定宽度与小数位；字符串类型在此指定最大字节数。</li><li><strong>宽度（Width）</strong>：变量显示与存储占用的字符总宽度，数值型与字符串型都适用。</li><li><strong>小数（Decimals）</strong>：数值型变量保留两位小数等显示位数。<strong>务必注意</strong>：这里只改变屏幕上显示的小数位，并不对原始数值做四舍五入——底层存储的是完整精度，显示成两位只是&quot;看上去&quot;被截断。</li><li><strong>标签（Label）</strong>：变量的中文或长说明，例如把 <code>chinese</code> 标为&quot;语文成绩&quot;。标签不参与运算，仅用于输出中替代生硬的代码名，提升可读性。</li><li><strong>值标签（Values）</strong>：为离散取值附加文字说明，例如给 <code>gender</code> 的 1 配&quot;男&quot;、2 配&quot;女&quot;。面向类别变量时，值标签让输出表格从一堆数字变为可读文字。</li><li><strong>缺失（Missing）</strong>：声明哪些取值代表缺失（详见 3.5 与 3.8 节）。</li><li><strong>列宽（Columns）</strong>：该列在 Data View 中显示的宽度，纯界面偏好，不影响数据。</li><li><strong>对齐（Align）</strong>：单元格内文字的左/中/右对齐方式，同样只关乎显示。</li><li><strong>度量标准（Measure）</strong>：即 3.1 节所述的 nominal / ordinal / scale，在此下拉选择。</li></ul><p>完成十列定义后，切到 Data View 即可录入数据。然而，纯图形点的方式难以复现、不易批量修改。更受教材与科研推崇的做法是用 <code>DATA LIST LIST</code> 语法一次性声明变量结构——它等价于在 Variable View 中把所有列填好，且可被保存为 <code>.sps</code> 文件反复运行。语法形式如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST</span></span>
<span class="line"><span>    /id (F4) name (A12) class (A1) gender (F1)</span></span>
<span class="line"><span>     chinese (F3) math (F3) english (F3)</span></span>
<span class="line"><span>     satisfaction (F1) attendance (F3).</span></span>
<span class="line"><span>VARIABLE LABELS</span></span>
<span class="line"><span>    id &#39;学号&#39; name &#39;姓名&#39; class &#39;班级&#39; gender &#39;性别&#39;</span></span>
<span class="line"><span>    chinese &#39;语文成绩&#39; math &#39;数学成绩&#39; english &#39;英语成绩&#39;</span></span>
<span class="line"><span>    satisfaction &#39;满意度(1-5)&#39; attendance &#39;出勤率&#39;.</span></span></code></pre></div><p><code>DATA LIST LIST</code> 后逐列写明变量名与格式。这里的 <code>F</code> 与 <code>A</code> 是<strong>格式类型字母</strong>（format type letter），并不是子命令——数值格式以 <code>F</code> 开头（如 <code>F4</code>、<code>F3</code>），字符串格式以 <code>A</code> 开头（如 <code>name (A12)</code>、<code>class (A1)</code>）；PSPP 的变量只有 numeric 与 string 两种类型，二者混排于同一数据定义之中即可声明整张表。紧接着的 <code>VARIABLE LABELS</code> 为各变量补上中文标签，相当于填好了 Variable View 的&quot;标签&quot;列。这套语法一旦写好，无论谁在何种机器上运行，得到的变量结构都分毫不差——这正是语法驱动工作流相对手工点选的最大优势。</p><h2 id="_3-3-数据录入与编辑" tabindex="-1">3.3 数据录入与编辑 <a class="header-anchor" href="#_3-3-数据录入与编辑" aria-label="Permalink to &quot;3.3 数据录入与编辑&quot;">​</a></h2><p>变量结构定义好之后，下一步是把具体数值填进表格。最直观的方式是在 Data View 中点击单元格直接键入（界面推断，手册未逐项文档化）：每一行对应一个学生，依次填入学号、姓名、各班成绩等。单元格录入胜在所见即所得，适合少量、零散的数据补录与修正。</p><p>但当数据量较大、或希望录入过程可复现时，应当回到语法：把 <code>DATA LIST</code> 与 <code>BEGIN DATA</code> / <code>END DATA</code> 配对使用，把全部数据作为语法的一部分一次性灌入。沿用 3.2 节的变量定义，完整的录入示例如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST</span></span>
<span class="line"><span>    /id (F4) name (A12) class (A1) gender (F1)</span></span>
<span class="line"><span>     chinese (F3) math (F3) english (F3)</span></span>
<span class="line"><span>     satisfaction (F1) attendance (F3).</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>1001 张伟  A 1  88  95  90  5  96</span></span>
<span class="line"><span>1002 李娜  B 2  92  88  85  4  91</span></span>
<span class="line"><span>1003 王芳  A 2  79  82  88  3  88</span></span>
<span class="line"><span>1004 刘洋  C 1  65  70  72  2  75</span></span>
<span class="line"><span>1005 陈静  B 2  95  91  93  5  98</span></span>
<span class="line"><span>1006 赵磊  C 1  58  63  60  1  70</span></span>
<span class="line"><span>END DATA.</span></span></code></pre></div><p>录入要点有三。其一，<code>DATA LIST</code> 与 <code>BEGIN DATA</code>/<code>END DATA</code> 必须三件套齐备、一一配对，缺一不可。其二，数据行须严格按变量定义的次序与宽度排列：字符串如 <code>name (A12)</code> 宽度足够，<code>class (A1)</code> 只占 1 字节故只写一个字母；数值按 <code>F</code> 格式对齐，字段间以空白分隔即可。其三也是最易踩的坑——<strong><code>END DATA.</code> 必须独占一行</strong>，且以英文句点收尾。若把 <code>END DATA.</code> 与某行数据写在同一行，或漏掉句点，PSPP 会继续把后续内容当作数据读取，导致结构错乱甚至语法报错。</p><p>运行上述代码片段后，六个学生的全部信息便落入活动数据集。此时在 Data View 中可见六行九列的完整表格；若此前已用 <code>VARIABLE LABELS</code> 加过标签，输出与浏览时列头将显示中文而非代码。需要指出的是，录入进内存的数据尚未存盘，关闭前务必用 <code>SAVE</code>（见 3.8 节）写出为 <code>.sav</code> 系统文件，否则改动会在退出时丢失。</p><h2 id="_3-4-从外部文件导入数据" tabindex="-1">3.4 从外部文件导入数据 <a class="header-anchor" href="#_3-4-从外部文件导入数据" aria-label="Permalink to &quot;3.4 从外部文件导入数据&quot;">​</a></h2><p>现实中大量数据已经存在于 Excel、OpenDocument 表格或 CSV/文本文件中，逐行手工键入既低效又易错。PSPP 提供了 <code>GET DATA</code> 命令专门读取这些外部格式，但有一个极易混淆的边界必须首先厘清。</p><p><strong><code>IMPORT</code> 与 <code>GET DATA</code> 是两回事。</strong> <code>IMPORT</code> 命令（详见 IMPORT 节点）只能读取 PSPP 自身的系统文件（<code>.sav</code>）与便携文件（<code>.por</code>），它无法直接打开 Excel 工作簿或 CSV 文本。凡遇到 Excel/ODS/CSV/纯文本，正确的入口永远是 <code>GET DATA</code>，而非 <code>IMPORT</code>。初学者常误以为&quot;导入&quot;都走 <code>IMPORT</code>，结果面对 <code>.xlsx</code> 无所适从——记住：外部表格用 <code>GET DATA</code>，PSPP 自家文件才用 <code>IMPORT</code>。</p><p><code>GET DATA</code> 通过 <code>/TYPE</code> 子命令区分来源，而 <code>/TYPE</code> 又是<strong>必须且必须作为第一个</strong>出现的子命令，取值包括 <code>GNM</code>（Gnumeric）、<code>ODS</code>（OpenDocument，兼容多数 <code>.ods</code> 及现代 Excel 导出的开放格式）、<code>PSQL</code>（PostgreSQL）与 <code>TXT</code>（文本/CSV）。下面分别给出两类最常见场景的完整语法。</p><p><strong>场景一：导入 Excel/ODS 电子表格</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET DATA /TYPE=ODS /FILE=&#39;students.ods&#39;</span></span>
<span class="line"><span>        /SHEET=NAME &#39;Sheet1&#39;</span></span>
<span class="line"><span>        /CELLRANGE=FULL</span></span>
<span class="line"><span>        /READNAMES=ON</span></span>
<span class="line"><span>        /ASSUMEDSTRWIDTH=32.</span></span></code></pre></div><p>关键子命令说明：<code>/SHEET=NAME &#39;Sheet1&#39;</code> 指定工作表，也可用 <code>/SHEET=INDEX n</code> 按序号选定；<code>/CELLRANGE=FULL</code> 读取整张表，亦可用 <code>/CELLRANGE=RANGE &#39;C3:P19&#39;</code> 仅取某个矩形区域；<code>/READNAMES=ON</code>（默认值即开启）把首行当作变量名读入，而非当作数据；<code>/ASSUMEDSTRWIDTH=32</code> 给未被显式指定宽度的字符串变量预设 32 字节——<strong>这一点尤其要留心</strong>，PSPP 对字符串宽度的默认假设偏窄，长文本列若不加此声明容易被截断，故建议显式给定足够宽度。</p><p><strong>场景二：导入 CSV/分隔文本</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET DATA /TYPE=TXT /FILE=&#39;students.csv&#39;</span></span>
<span class="line"><span>        /ARRANGEMENT=DELIMITED</span></span>
<span class="line"><span>        /DELIMITERS=&#39;,&#39;</span></span>
<span class="line"><span>        /FIRSTCASE=2</span></span>
<span class="line"><span>        /VARIABLES=id F4 name A12 class A1 gender F1</span></span>
<span class="line"><span>                    chinese F3 math F3 english F3</span></span>
<span class="line"><span>                    satisfaction F1 attendance F3.</span></span></code></pre></div><p>此处 <code>/ARRANGEMENT=DELIMITED</code> 表明文件以分隔符划分字段；<code>/DELIMITERS=&#39;,&#39;</code> 指明逗号分隔，制表符需用 <code>\\t</code> 表示；<code>/FIRSTCASE=2</code> 告知程序跳过第 1 行表头、从第 2 行起读数据——<strong>忘记这一行，表头文字会被当成第一条个案，字符串列尚能容错、数值列则会引入脏数据</strong>。最后的 <code>/VARIABLES=</code> 逐个列出变量名与格式，<strong>它必须放在所有子命令的最后</strong>，且是必填项：PSPP 不会像电子表格那样自动推断类型，而要靠你在这里明确每份字段是 <code>F</code>（数值）还是 <code>A</code>（字符串）及其宽度。</p><p>无论哪种导入，结果都进入内存中的活动数据集，原文件不被改动。读完建议立即用 <code>SAVE</code> 落盘为 <code>.sav</code>，以免重复导入。若导入后字符串出现莫名截断或首行混入了表头，回头检查 <code>/ASSUMEDSTRWIDTH</code> 与 <code>/FIRSTCASE</code> 这两项即可定位。</p><h2 id="_3-5-变量属性的深入设置" tabindex="-1">3.5 变量属性的深入设置 <a class="header-anchor" href="#_3-5-变量属性的深入设置" aria-label="Permalink to &quot;3.5 变量属性的深入设置&quot;">​</a></h2><p>建好变量、录入数据之后，真正的&quot;数据管理工作&quot;才刚开始。一份能被统计过程正确理解的数据，离不开对标签、值标签、缺失值与度量标准的精细设定。这些属性在 Variable View 中可点选设置，也可用对应命令一次性批量声明——后者显然更利于复现。</p><p><strong>变量标签 <code>VARIABLE LABELS</code></strong> 为变量附加说明文字，输出表格的列头将显示标签而非代码：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VARIABLE LABELS gender &#39;性别&#39; satisfaction &#39;课程满意度(1-5)&#39; attendance &#39;出勤率(%)&#39;.</span></span></code></pre></div><p><strong>值标签 <code>VALUE LABELS</code></strong> 为离散取值对应文字，是类别变量可读化的关键。需要特别记住：<code>VALUE LABELS</code> 会<strong>清空</strong>该变量已有的全部值标签后再写入，因此它适合首次定义；若要在此基础上追加而不破坏既有标签，须改用 <code>ADD VALUE LABELS</code>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VALUE LABELS gender 1 &#39;男&#39; 2 &#39;女&#39;.</span></span>
<span class="line"><span>ADD VALUE LABELS satisfaction 1 &#39;非常不满意&#39; 2 &#39;不满意&#39; 3 &#39;一般&#39; 4 &#39;满意&#39; 5 &#39;非常满意&#39;.</span></span></code></pre></div><p>上面先为 <code>gender</code> 定义男女，再用 <code>ADD VALUE LABELS</code> 把满意度的五级文字补上，二者互不干扰。若误用 <code>VALUE LABELS</code> 去加第五级，前面四级的标签将被一扫而空。</p><p><strong>缺失值 <code>MISSING VALUES</code></strong> 声明哪些取值代表&quot;缺失&quot;，是数据清洗的基石（详见 3.8 节）。数值型变量最多可声明 3 个离散缺失值，或一个连续范围；字符串变量规则相同。范围用 <code>THRU</code> 衔接，端点可用 <code>LO</code>/<code>LOWEST</code> 与 <code>HI</code>/<code>HIGHEST</code> 指代最小、最大边界：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MISSING VALUES attendance (999) satisfaction (LO THRU 0).</span></span></code></pre></div><p>本例把出勤率的 <code>999</code>（明显不可能的值）与满意度中&quot;0 及更小&quot;的区间一并标为缺失。此后多数统计过程默认将这些取值排除在计算之外，从而免于污染均值与标准差。</p><p><strong>度量标准 <code>VARIABLE LEVEL</code></strong> 显式指定变量的测量尺度，呼应 3.1 节的铺垫：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VARIABLE LEVEL gender class (NOMINAL) satisfaction (ORDINAL)</span></span>
<span class="line"><span>               chinese math english attendance (SCALE).</span></span></code></pre></div><p>这样，<code>gender</code> 与 <code>class</code> 被标为名义、<code>satisfaction</code> 为有序、各成绩与出勤率为标度。过程在默认行为上会参考这一设定，例如对名义变量避免给出无意义的均值。把 3.5 节的四条命令与 3.2、3.3 节的建表录入串成一段语法，便构成了这份学生数据集&quot;从结构到语义&quot;的完整定义，后续所有分析都建立在它之上。</p><h2 id="_3-6-数据整理-排序、拆分文件、选择个案" tabindex="-1">3.6 数据整理：排序、拆分文件、选择个案 <a class="header-anchor" href="#_3-6-数据整理-排序、拆分文件、选择个案" aria-label="Permalink to &quot;3.6 数据整理：排序、拆分文件、选择个案&quot;">​</a></h2><p>数据落盘之后，往往要先按分析意图重新排列或切分，再交给统计过程。这一节的三组命令分别解决&quot;排顺序&quot;&quot;分组算&quot;&quot;取子集&quot;三类需求。</p><p><strong><code>SORT CASES</code></strong> 按指定变量对个案重新排序，菜单路径为 Data → Sort Cases【手册明示】。语法中可用 <code>(D)</code> 或 <code>(DOWN)</code> 表示降序，<code>(A)</code> 或 <code>(UP)</code> 表示升序，省略则默认升序：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SORT CASES BY class (A) chinese (D).</span></span></code></pre></div><p>上述命令先按班级升序、班级内再按语文成绩降序排列六个学生。需要强调：<code>SORT CASES</code> 只改变内存中活动数据集的行序，<strong>不会改动原 <code>.sav</code> 文件</strong>，要保留排序结果仍需 <code>SAVE</code>。</p><p><strong><code>SPLIT FILE</code></strong> 让后续统计过程按某个（或几个）分组变量分别出具结果，而不必手动拆表。它有两种模式：<code>LAYERED</code>（默认，各组的表合并在同一输出中便于对照）与 <code>SEPARATE</code>（每组独立成表）。关闭拆分用 <code>SPLIT FILE OFF.</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SORT CASES BY class (A).</span></span>
<span class="line"><span>SPLIT FILE LAYERED BY class.</span></span></code></pre></div><p>这里先按 <code>class</code> 排序再拆分，次序并非偶然——<code>SPLIT FILE</code> 在分组时只识别<strong>相邻的同类个案</strong>，若事先未排序，同一班级的学生可能分散在多处，拆分出的结果就会支离破碎。拆分效果会一直持续，直到显式 <code>SPLIT FILE OFF.</code> 才解除，因此分析完一组后别忘了关掉，否则后续无关过程也会被无谓分组。</p><p><strong><code>SELECT IF</code> 与 <code>FILTER</code></strong> 都用于&quot;只保留部分个案&quot;，但性质截然相反，这是本节最需警觉的分水岭。<code>SELECT IF</code> 会<strong>永久删除</strong>不满足条件的个案——除非用 <code>TEMPORARY</code> 包裹，否则被剔除的数据无从恢复：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT IF attendance &gt;= 75.</span></span></code></pre></div><p>执行后，出勤率低于 75 的学生（如示例中 <code>attendance</code> 为 70 的赵磊）将从数据集中彻底消失。相比之下，<code>FILTER</code> 只是&quot;过滤&quot;而非&quot;删除&quot;：被过滤变量取值为 0 或缺失的个案在分析中暂时隐藏，却仍留在数据集里，用 <code>FILTER OFF.</code> 即可原样恢复：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>COMPUTE flag = (attendance &gt;= 75).</span></span>
<span class="line"><span>FILTER BY flag.</span></span>
<span class="line"><span>* 此时低于75的个案被暂时排除，但数据仍在</span></span>
<span class="line"><span>FILTER OFF.</span></span></code></pre></div><p>一个来自手册的 <code>SELECT IF</code> 实例是 <code>SELECT IF dob &gt; date.dmy(31,12,1999).</code>，即仅保留 1999 年底之后出生者。请务必牢记：删除不可逆，过滤可恢复。在拿不准该不该丢掉数据时，优先用 <code>FILTER</code> 试探，确认无误后再考虑 <code>SELECT IF</code>。</p><h2 id="_3-7-变量计算与重新编码" tabindex="-1">3.7 变量计算与重新编码 <a class="header-anchor" href="#_3-7-变量计算与重新编码" aria-label="Permalink to &quot;3.7 变量计算与重新编码&quot;">​</a></h2><p>原始数据 seldom 直接满足分析需要：常常要由既有变量算出新指标，或把连续分数归并成等级。PSPP 提供 <code>COMPUTE</code> 与 <code>RECODE</code> 两件利器应对这两种场景。</p><p><strong><code>COMPUTE</code></strong> 按表达式生成（或覆盖）一个变量，语法为 <code>COMPUTE variable = expression.</code>。若目标变量是数值型且尚不存在，PSPP 会自动新建它，默认格式 <code>F8.2</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>COMPUTE total = chinese + math + english.</span></span>
<span class="line"><span>COMPUTE average = total / 3.</span></span></code></pre></div><p>这两行算出了每个学生的总分与三科平均。然而，当目标变量是<strong>字符串</strong>时，绝不可依赖自动新建——必须先以 <code>STRING</code> 命令显式声明其宽度，否则 <code>COMPUTE</code> 会因目标类型不明而报错或产生不可预期结果：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>STRING remark (A6).</span></span>
<span class="line"><span>COMPUTE remark = &#39;已录入&#39;.</span></span></code></pre></div><p>这里先用 <code>STRING remark (A6).</code> 把目标建成 6 字节字符串，再将 <code>COMPUTE</code> 的结果写入，次序不可颠倒。菜单上对应操作位于 Transform → Compute Variable（界面推断，手册未逐项文档化）。</p><p><strong><code>RECODE</code></strong> 把变量的取值按规则映射为新值，常用于分数分级、异常值归并。语法为 <code>RECODE src_vars (源值 = 目标值) … [INTO dest_vars].</code>，省略 <code>INTO</code> 则就地改写源变量，写上 <code>INTO</code> 则把结果存入新变量、保留原值。它支持丰富的特殊记号：<code>THRU</code> 表示含端点的区间；<code>LO</code>/<code>LOWEST</code> 与 <code>HI</code>/<code>HIGHEST</code> 指代最小、最大边界；<code>MISSING</code>、<code>SYSMIS</code> 匹配缺失；<code>ELSE</code> 兜住前面未覆盖的一切（<strong>必须放在最后一组</strong>）；<code>COPY</code> 表示原样保留；<code>(CONVERT)</code> 可把数值型字符串先转为数值再判断。多组规则之间用 <code>/</code> 分隔。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RECODE total</span></span>
<span class="line"><span>    (LOWEST THRU 179 = 1)</span></span>
<span class="line"><span>    (180 THRU 209 = 2)</span></span>
<span class="line"><span>    (210 THRU 239 = 3)</span></span>
<span class="line"><span>    (240 THRU HIGHEST = 4)</span></span>
<span class="line"><span>    INTO level_num.</span></span>
<span class="line"><span>ADD VALUE LABELS level_num 1 &#39;不及格&#39; 2 &#39;及格&#39; 3 &#39;良好&#39; 4 &#39;优秀&#39;.</span></span></code></pre></div><p>上面把总分划为四级并写入新变量 <code>level_num</code>，再用 <code>ADD VALUE LABELS</code> 配文字。若想把等级直接存成字符串字母，则目标须先 <code>STRING</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>STRING grade (A6).</span></span>
<span class="line"><span>RECODE total</span></span>
<span class="line"><span>    (LOWEST THRU 179 = &#39;不及格&#39;)</span></span>
<span class="line"><span>    (180 THRU 209 = &#39;及格&#39;)</span></span>
<span class="line"><span>    (210 THRU 239 = &#39;良好&#39;)</span></span>
<span class="line"><span>    (240 THRU HIGHEST = &#39;优秀&#39;)</span></span>
<span class="line"><span>    INTO grade.</span></span></code></pre></div><p>另一个展示 <code>SYSMIS</code> 与 <code>COPY</code> 的手册式示例是 <code>RECODE x y (0 = 99) (1 THRU 10 = COPY) (1000 THRU HIGHEST = SYSMIS) (ELSE = 999).</code>：它把 0 改写为 99、1~10 原样保留、1000 及以上标为系统缺失、其余一律填 999。善用这些记号，重新编码既能清理异常，又能无损地衍生出可供分组分析的新类别变量。</p><h2 id="_3-8-数据清洗与缺失值处理" tabindex="-1">3.8 数据清洗与缺失值处理 <a class="header-anchor" href="#_3-8-数据清洗与缺失值处理" aria-label="Permalink to &quot;3.8 数据清洗与缺失值处理&quot;">​</a></h2><p>把前面各节串起来，数据管理的最终落点便是清洗：识别并妥善处理脏数据与缺失值，再把整理好的数据集稳妥保存。<code>MISSING VALUES</code>（3.5 节）所定义的那些取值，在 PSPP 中称为<strong>用户缺失值</strong>（user-missing）。它们的关键作用在于：多数统计过程默认会将用户缺失值在分析中排除，例如 <code>DESCRIPTIVES</code> 默认 <code>NOINCLUDE</code>，意味着被标为缺失的出勤率 <code>999</code> 不会进入均值与标准差的计算，从而避免一个荒谬的取值拉偏整列统计量。若确有需要把缺失值也纳入，才须显式附加 <code>INCLUDE</code> 子命令——这一默认排除机制，正是 3.5 节强调&quot;先标缺失、再算统计&quot;的原因。</p><p>一套完整的清洗流程通常如下：先以 <code>MISSING VALUES</code> 锁定异常码（如 <code>attendance (999)</code>），必要时用 <code>RECODE</code> 把这些异常归并或标为缺失；再以 <code>SELECT IF</code> 或 <code>FILTER</code> 剔除无效个案（注意前者的不可逆性）；随后用 <code>COMPUTE</code> 与 <code>RECODE</code> 衍生分析所需的总分、等级等变量；最后把内存中这版干净数据写出为系统文件，供后续章节的统计分析直接读取：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* 数据清洗与保存示例</span></span>
<span class="line"><span>MISSING VALUES attendance (999).</span></span>
<span class="line"><span>COMPUTE total = chinese + math + english.</span></span>
<span class="line"><span>RECODE total (LOWEST THRU 179 = 1)(180 THRU 209 = 2)</span></span>
<span class="line"><span>           (210 THRU 239 = 3)(240 THRU HIGHEST = 4) INTO level_num.</span></span>
<span class="line"><span>ADD VALUE LABELS level_num 1 &#39;不及格&#39; 2 &#39;及格&#39; 3 &#39;良好&#39; 4 &#39;优秀&#39;.</span></span>
<span class="line"><span>SAVE OUTFILE=&#39;students_clean.sav&#39;.</span></span></code></pre></div><p>收尾的 <code>SAVE OUTFILE=&#39;students_clean.sav&#39;.</code> 把清洗后的活动数据集持久化为 PSPP 系统文件。需要认清：<code>SAVE</code> 写出的是当前内存中的全部内容——包括排序结果、拆分状态解除后的数据、以及所有新建与重编码的变量；而像 <code>SPLIT FILE</code> 这类&quot;过程状态&quot;本身不会被存进文件。此后在第四章及以后的描述统计中，只需 <code>IMPORT</code> 读回这份 <code>.sav</code>，便能以一份语义清晰、缺失妥善处理的数据，直接进入均值、频率与图表的分析，不必再重复本章的整理劳动。</p><p>至此，从理解变量类型、建表定义、录入与导入，到属性设定、排序拆分筛选、计算重编码，直至清洗保存，数据管理的完整链路已经闭合。它所产出的那份干净数据集，正是全书中所有统计操作的共同起点。</p>`,80)])])}const h=s(c,[["render",t]]);export{E as __pageData,h as default};
